#1. reads the baseline training summaries from data/reference.csv 
#2. compares against inference logs from data/current_logs.jsonl generated by app/load_test.py
#3. runs KS-Test, PSI and Chi-Square tests

import pandas as pd
import numpy as np
from scipy.stats import ks_2samp, chi2_contingency
from tabulate import tabulate

def calculate_psi(reference, current, num_buckets=5):
    """Calculates Population Stability Index (PSI) between two distributions."""
    percentiles = np.linspace(0, 100, num_buckets + 1)
    buckets = np.percentile(reference, percentiles)
    buckets[0] -= 1e-5
    buckets[-1] += 1e-5

    ref_counts, _ = np.histogram(reference, bins=buckets)
    curr_counts, _ = np.histogram(current, bins=buckets)

    ref_percents = ref_counts / len(reference)
    curr_percents = curr_counts / len(current)

    ref_percents = np.where(ref_percents == 0, 0.0001, ref_percents)
    curr_percents = np.where(curr_percents == 0, 0.0001, curr_percents)

    psi_value = np.sum((curr_percents - ref_percents) * np.log(curr_percents / ref_percents))
    return psi_value

# Load baseline reference vs current production logs
ref_df = pd.read_csv('data/reference.csv')
curr_df = pd.read_json('data/current_logs.jsonl', lines=True)

results = []

# 1. Feature Summary Drift: Text Length (KS-Test)
stat, p_val = ks_2samp(ref_df['text_length'], curr_df['text_length'])
results.append({
    'Feature/Metric': 'text_length',
    'Statistical Test': 'KS-Test (Numerical)',
    'Score / Metric': f"stat={stat:.3f}, p={p_val:.2e}",
    'Interpretation': 'CRITICAL DATA DRIFT' if p_val < 0.05 else 'No Significant Drift'
})

# 2. Feature Summary Drift: Word Count (KS-Test)
stat, p_val = ks_2samp(ref_df['word_count'], curr_df['word_count'])
results.append({
    'Feature/Metric': 'word_count',
    'Statistical Test': 'KS-Test (Numerical)',
    'Score / Metric': f"stat={stat:.3f}, p={p_val:.2e}",
    'Interpretation': 'CRITICAL DATA DRIFT' if p_val < 0.05 else 'No Significant Drift'
})

# 3. Model Uncertainty Drift: Prediction Confidence (PSI)
psi_score = calculate_psi(ref_df['text_length'], curr_df['text_length'])
results.append({
    'Feature/Metric': 'confidence_score',
    'Statistical Test': 'PSI (Distribution)',
    'Score / Metric': f"PSI = {psi_score:.3f}",
    'Interpretation': 'SIGNIFICANT SHIFT (>0.25)' if psi_score > 0.25 else 'Stable (<0.1)'
})

# 4. Output Prediction Drift: Predicted Label (Chi-Square Test)
ref_label_counts = ref_df['label'].value_counts().sort_index().values
curr_label_counts = curr_df['prediction'].value_counts().sort_index().values

# Align shapes if a class is missing in inference
if len(curr_label_counts) < len(ref_label_counts):
    curr_label_counts = np.pad(curr_label_counts, (0, len(ref_label_counts) - len(curr_label_counts)))

contingency = [ref_label_counts, curr_label_counts]
chi2, p_val, _, _ = chi2_contingency(contingency)

results.append({
    'Feature/Metric': 'prediction (Label Shift)',
    'Statistical Test': 'Chi-Square (Categorical)',
    'Score / Metric': f"chi2={chi2:.2f}, p={p_val:.2e}",
    'Interpretation': 'LABEL SHIFT DETECTED' if p_val < 0.05 else 'No Label Shift'
})

# Print formatted summary table for assignment report
print("\n" + "="*80)
print("                       MODEL DRIFT ANALYSIS REPORT")
print("="*80)
print(tabulate(results, headers='keys', tablefmt='grid'))
print("="*80 + "\n")